import sqlite3
from contextlib import closing
from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel, Field
from starlette.responses import Response

app = FastAPI(title="CommunityStepMetrics", version="1.0.0")

DATABASE = "db.sqlite3"


def init_db():
    """Create the submissions table and index if they don't exist."""
    with closing(sqlite3.connect(DATABASE)) as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                cell_lat REAL NOT NULL,
                cell_lon REAL NOT NULL,
                steps INTEGER NOT NULL
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cell ON submissions(cell_lat, cell_lon)"
        )
        conn.commit()


@app.on_event("startup")
def startup():
    init_db()


class StepRequest(BaseModel):
    lat: float
    lon: float
    steps: int


class AverageResponse(BaseModel):
    average_steps: float
    submission_count: int


@app.post("/steps", status_code=201)
def submit_steps(req: StepRequest):
    """Store a step submission after rounding coordinates to one decimal."""
    cell_lat = round(req.lat, 1)
    cell_lon = round(req.lon, 1)

    try:
        with closing(sqlite3.connect(DATABASE)) as conn:
            conn.execute(
                "INSERT INTO submissions (cell_lat, cell_lon, steps) VALUES (?, ?, ?)",
                (cell_lat, cell_lon, req.steps),
            )
            conn.commit()
    except Exception as e:
        raise HTTPException(status_code=400, detail="Database error")

    return Response(status_code=201)


@app.get("/average", response_model=AverageResponse)
def get_average(
    lat: float = Query(..., description="Latitude for grid cell lookup"),
    lon: float = Query(..., description="Longitude for grid cell lookup"),
):
    """Return average steps and submission count for the rounded grid cell."""
    cell_lat = round(lat, 1)
    cell_lon = round(lon, 1)

    try:
        with closing(sqlite3.connect(DATABASE)) as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.execute(
                "SELECT COUNT(*) AS cnt, AVG(steps) AS avg_steps FROM submissions WHERE cell_lat = ? AND cell_lon = ?",
                (cell_lat, cell_lon),
            )
            row = cur.fetchone()
            if row is None or row["cnt"] == 0:
                return {"average_steps": 0.0, "submission_count": 0}
            return {"average_steps": row["avg_steps"], "submission_count": row["cnt"]}
    except Exception as e:
        raise HTTPException(status_code=400, detail="Database error")


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=5000)
